begin;
create schema if not exists extensions;
create extension if not exists postgis with schema extensions;

create table public.province_boundaries (
  province_code text primary key check (province_code = '25'),
  name text not null,
  boundary extensions.geometry(MultiPolygon, 4326) not null
);
alter table public.province_boundaries enable row level security;
revoke all on public.province_boundaries from anon, authenticated;
grant select on public.province_boundaries to anon, authenticated;
create policy boundary_read on public.province_boundaries for select to anon, authenticated using (true);

