create table public.flood_reports (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null default auth.uid() references auth.users(id),
  type text not null check (type in ('help', 'flood')),
  description text not null check (char_length(btrim(description)) between 1 and 300),
  people integer check (people between 1 and 999),
  latitude double precision not null check (latitude between -90 and 90),
  longitude double precision not null check (longitude between -180 and 180),
  province_code text not null default '25' references public.province_boundaries(province_code) check (province_code = '25'),
  status text not null default 'pending' check (status in ('pending', 'done')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index flood_reports_created_at_idx on public.flood_reports(created_at desc, id);
create index flood_reports_owner_idx on public.flood_reports(owner_id);
alter table public.flood_reports enable row level security;
revoke all on public.flood_reports from anon, authenticated;
grant select on public.flood_reports to anon, authenticated;
grant insert (type, description, people, latitude, longitude) on public.flood_reports to authenticated;
grant update (status) on public.flood_reports to authenticated;
create policy reports_read on public.flood_reports for select to anon, authenticated using (true);
create policy reports_create on public.flood_reports for insert to authenticated
  with check (owner_id = (select auth.uid()) and status = 'pending');
create policy reports_update on public.flood_reports for update to authenticated
  using (owner_id = (select auth.uid()) or (select auth.jwt()->'app_metadata'->>'role') in ('rescuer', 'admin'))
  with check (owner_id = (select auth.uid()) or (select auth.jwt()->'app_metadata'->>'role') in ('rescuer', 'admin'));

create table public.report_contacts (
  report_id uuid primary key references public.flood_reports(id) on delete cascade,
  phone text not null check (char_length(phone) between 6 and 20 and phone ~ '^[+0-9 ()-]+$')
);
alter table public.report_contacts enable row level security;
revoke all on public.report_contacts from anon, authenticated;
-- anon can reach the relationship but RLS returns no contact rows.
grant select on public.report_contacts to anon, authenticated;
grant insert on public.report_contacts to authenticated;
create policy contacts_read on public.report_contacts for select to authenticated
  using ((select auth.jwt()->'app_metadata'->>'role') in ('rescuer', 'admin') or
    exists (select 1 from public.flood_reports r where r.id = report_id and r.owner_id = (select auth.uid())));
create policy contacts_create on public.report_contacts for insert to authenticated
  with check (exists (select 1 from public.flood_reports r where r.id = report_id and r.owner_id = (select auth.uid())));

create function public.validate_flood_report() returns trigger
language plpgsql security invoker set search_path = '' as $$
begin
  if not exists (
    select 1 from public.province_boundaries b where b.province_code = '25'
    and extensions.st_covers(b.boundary, extensions.st_setsrid(extensions.st_makepoint(new.longitude, new.latitude), 4326))
  ) then
    raise exception 'outside_prachinburi' using errcode = '23514';
  end if;
  if tg_op = 'UPDATE' and (new.id, new.owner_id, new.type, new.description, new.people, new.latitude, new.longitude, new.province_code, new.created_at)
    is distinct from (old.id, old.owner_id, old.type, old.description, old.people, old.latitude, old.longitude, old.province_code, old.created_at) then
    raise exception 'Only report status can be updated' using errcode = '42501';
  end if;
  new.updated_at = now();
  return new;
end;
$$;
revoke all on function public.validate_flood_report() from public, anon, authenticated;
create trigger validate_report before insert or update on public.flood_reports
  for each row execute function public.validate_flood_report();

create function public.submit_flood_report(p_type text, p_description text, p_latitude double precision,
  p_longitude double precision, p_people integer default null, p_phone text default null) returns uuid
language plpgsql security invoker set search_path = '' as $$
declare report_id uuid;
begin
  if auth.uid() is null then raise exception 'Authentication required' using errcode = '42501'; end if;
  insert into public.flood_reports(type, description, latitude, longitude, people)
    values(p_type, btrim(p_description), p_latitude, p_longitude, p_people) returning id into report_id;
  if nullif(btrim(p_phone), '') is not null then
    insert into public.report_contacts(report_id, phone) values(report_id, btrim(p_phone));
  end if;
  return report_id;
end;
$$;
revoke all on function public.submit_flood_report(text, text, double precision, double precision, integer, text) from public, anon;
grant execute on function public.submit_flood_report(text, text, double precision, double precision, integer, text) to authenticated;
grant all on public.province_boundaries, public.flood_reports, public.report_contacts to service_role;
commit;
